// --- BusinessDays.view.tsx ---
import { Button, ConfirmModal, InfoBanner, Input, Spinner } from '@microteia/ui';



/**
 * The business-day calendars, in four files: this one renders, `BusinessDays.viewmodel.tsx` holds the
 * draft and the gestures, `BusinessDays.styles.tsx` holds the styles and `BusinessDays.rules.ts` holds
 * what a test can call.
 *
 * On the left, the calendars. On the right, the selected one: its name and key, the weekdays that are
 * never business days, its years, and the twelve months of the chosen year — click a day to mark it,
 * drag across a period to mark it all.
 */
export default function BusinessDaysView() {
  const vm = useBusinessDaysViewModel();

  if (vm.screenMissing) {
    return (
      <S.Missing>
        <InfoBanner message={vm.t('view.screen-missing')} variant="warning" />
      </S.Missing>
    );
  }

  if (vm.isLoading) return <Spinner />;

  return (
    <S.Layout>
      <S.Panel>
        <S.PanelTitle>{vm.t('view.calendars')}</S.PanelTitle>
        {vm.calendars.length === 0 ? <S.Muted>{vm.t('view.empty')}</S.Muted> : null}
        <S.CalendarList>
          {vm.calendars.map((calendar) => (
            <S.CalendarItem
              key={calendar.id}
              type="button"
              $active={calendar.id === vm.activeId}
              onClick={() => vm.selectCalendar(calendar.id)}
            >
              <S.CalendarName>{calendar.name}</S.CalendarName>
              <S.CalendarKey>{calendar.key}</S.CalendarKey>
            </S.CalendarItem>
          ))}
        </S.CalendarList>
        {vm.canCreate ? (
          <Button variant="secondary" size="sm" onClick={vm.createCalendar}>
            {vm.t('view.new-calendar')}
          </Button>
        ) : null}
      </S.Panel>

      {vm.hasCalendar ? (
        <S.Panel>
          <S.FieldRow>
            <S.Field>
              {vm.t('view.name')}
              <Input value={vm.draft.name} disabled={!vm.canEdit} onChange={(event) => vm.setName(event.target.value)} />
            </S.Field>
            <S.Field>
              {vm.t('view.key')}
              <Input value={vm.draft.key} disabled={!vm.canEdit} onChange={(event) => vm.setKey(event.target.value)} />
              <S.Hint>{vm.t('view.key.hint')}</S.Hint>
            </S.Field>
          </S.FieldRow>

          <S.Row>
            <S.RowLabel>{vm.t('view.weekend')}</S.RowLabel>
            {vm.weekdayNames.map((name, weekday) => (
              <S.Chip
                key={name}
                type="button"
                $active={vm.draft.weekend.includes(weekday)}
                disabled={!vm.canEdit}
                onClick={() => vm.toggleWeekday(weekday)}
              >
                {name}
              </S.Chip>
            ))}
          </S.Row>

          <S.Row>
            <S.RowLabel>{vm.t('view.years')}</S.RowLabel>
            {vm.years.map((year) => (
              <S.Chip key={year} type="button" $active={year === vm.activeYear} onClick={() => vm.selectYear(year)}>
                {year}
              </S.Chip>
            ))}
            {vm.canEdit ? (
              <S.Chip type="button" onClick={vm.addYear}>
                {vm.t('view.add-year', { year: vm.yearToAdd })}
              </S.Chip>
            ) : null}
            {vm.canEdit && vm.canCopy ? (
              <S.Chip type="button" onClick={vm.copyToNextYear}>
                {vm.t('view.copy-year', { year: vm.copyTarget })}
              </S.Chip>
            ) : null}
            {vm.canEdit && vm.activeYear ? (
              <S.Chip type="button" onClick={() => vm.askRemoveYear(vm.activeYear ?? '')}>
                {vm.t('view.remove-year', { year: vm.activeYear })}
              </S.Chip>
            ) : null}
          </S.Row>

          {vm.activeYear ? (
            <>
              <S.Row>
                <S.Muted>{vm.t('view.marked', { count: vm.markedCount, year: vm.activeYear })}</S.Muted>
                <S.Spacer />
                <S.LegendItem>
                  <S.LegendSwatch $state="off" />
                  {vm.t('view.legend.off')}
                </S.LegendItem>
                <S.LegendItem>
                  <S.LegendSwatch $state="weekend" />
                  {vm.t('view.legend.weekend')}
                </S.LegendItem>
              </S.Row>
              <S.Months>
                {vm.months.map((month) => (
                  <S.Month key={month.month}>
                    <S.MonthName>{month.name}</S.MonthName>
                    <S.Week>
                      {vm.weekdayInitials.map((initial, index) => (
                        <S.WeekdayHead key={index}>{initial}</S.WeekdayHead>
                      ))}
                    </S.Week>
                    {month.rows.map((row, rowIndex) => (
                      <S.Week key={rowIndex}>
                        {row.map((cell, cellIndex) =>
                          cell ? (
                            <S.Day
                              key={cell.day}
                              type="button"
                              $state={cell.state}
                              $editable={vm.canEdit}
                              onPointerDown={() => vm.onDayDown(cell)}
                              onPointerEnter={() => vm.onDayEnter(cell)}
                            >
                              {cell.label}
                            </S.Day>
                          ) : (
                            <S.EmptyDay key={cellIndex} />
                          ),
                        )}
                      </S.Week>
                    ))}
                  </S.Month>
                ))}
              </S.Months>
            </>
          ) : (
            <InfoBanner message={vm.t('view.no-years')} variant="info" />
          )}

          <S.Row>
            {vm.canDelete ? (
              <Button variant="ghost" size="sm" onClick={vm.askDelete}>
                {vm.t('view.delete')}
              </Button>
            ) : null}
            <S.Spacer />
            {vm.isDirty ? (
              <Button variant="ghost" size="sm" onClick={vm.discard}>
                {vm.t('view.discard')}
              </Button>
            ) : null}
            {vm.canEdit ? (
              <Button variant="primary" size="sm" disabled={!vm.isDirty} $isLoading={vm.saving} onClick={vm.save}>
                {vm.t('view.save')}
              </Button>
            ) : null}
          </S.Row>
        </S.Panel>
      ) : (
        <S.Panel>
          <S.Muted>{vm.t('view.select')}</S.Muted>
        </S.Panel>
      )}

      <ConfirmModal
        isOpen={vm.confirmation !== null}
        title={vm.confirmTitle}
        message={vm.confirmMessage}
        confirmLabel={vm.confirmLabel}
        cancelLabel={vm.t('view.cancel')}
        variant="danger"
        onConfirm={vm.confirm}
        onCancel={vm.cancelConfirmation}
      />
    </S.Layout>
  );
}

// --- BusinessDays.viewmodel.tsx ---
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useCan, useCreateRecord, useDeleteRecord, useEntity, useNotify, useUpdateRecord } from '@microteia/data';
import { useLocale, useT } from '@microteia/i18n';



















const SOURCE_ID = 'microteia:business-calendars';

type DayState = 'off' | 'weekend' | 'business';

interface DayCell {
  day: string;
  label: number;
  state: DayState;
}

interface MonthView {
  month: number;
  name: string;
  rows: (DayCell | null)[][];
}

type Confirmation = { kind: 'delete' } | { kind: 'remove-year'; year: string } | null;

/**
 * The state, the data and the gestures — and no JSX.
 *
 * What the grid edits is a DRAFT per calendar, kept apart from the stored record: marking days is a
 * dozen clicks, and saving each one would hand the formulas a calendar that is half marked. The draft
 * is derived — the stored record unless the person changed something — so nothing has to be copied
 * into state by an effect.
 */
export const useBusinessDaysViewModel = () => {
  const t = useT('com.microteia.business-days');
  const { locale } = useLocale();
  const entity = useEntity(SOURCE_ID);
  const createRecord = useCreateRecord();
  const updateRecord = useUpdateRecord();
  const deleteRecord = useDeleteRecord();
  const notify = useNotify();
  const can = useCan();

  const collection = entity.collection;
  const records = entity.records;

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [edits, setEdits] = useState<Record<string, CalendarDraft>>({});
  const [yearChoice, setYearChoice] = useState<string | null>(null);
  const [painting, setPainting] = useState<boolean | null>(null);
  const [confirmation, setConfirmation] = useState<Confirmation>(null);
  const [saving, setSaving] = useState(false);
  const [currentYear] = useState(() => new Date().getFullYear());

  const calendars = useMemo(
    () =>
      records
        .map((record) => ({ id: record.id as string, name: String(record.name || record.key || record.id), key: String(record.key ?? '') }))
        .sort((left, right) => left.name.localeCompare(right.name, locale)),
    [records, locale],
  );

  const activeId = selectedId && calendars.some((calendar) => calendar.id === selectedId)
    ? selectedId
    : calendars[0]?.id ?? null;
  const record = useMemo(() => records.find((item) => item.id === activeId) ?? null, [records, activeId]);
  const stored = useMemo(() => draftOf(record), [record]);
  const pending = activeId ? edits[activeId] : undefined;
  const draft = pending ?? stored;
  const isDirty = !!pending && !sameDraft(pending, stored);

  const years = yearsOf(draft);
  const activeYear =
    yearChoice && draft.years[yearChoice]
      ? yearChoice
      : years.includes(String(currentYear))
        ? String(currentYear)
        : years[years.length - 1] ?? null;

  const canEdit = !!collection && can(`${collection}.update`);
  const canCreate = !!collection && can(`${collection}.create`);
  const canDelete = !!collection && can(`${collection}.delete`);

  const weekdayNames = useMemo(() => weekdayNamesOf(locale, 'short'), [locale]);
  const weekdayInitials = useMemo(() => weekdayNamesOf(locale, 'narrow'), [locale]);

  const months = useMemo((): MonthView[] => {
    if (!activeYear) return [];
    const year = Number(activeYear);
    const marked = new Set(draft.years[activeYear] ?? []);
    const weekend = new Set(draft.weekend);
    return Array.from({ length: 12 }, (_, index) => ({
      month: index + 1,
      name: monthNameOf(locale, year, index + 1),
      rows: monthGridOf(year, index + 1).map((row) =>
        row.map((day) => {
          if (!day) return null;
          const state: DayState = marked.has(day) ? 'off' : weekend.has(weekdayOf(day)) ? 'weekend' : 'business';
          return { day, label: Number(day.slice(8)), state };
        }),
      ),
    }));
  }, [activeYear, draft, locale]);

  const markedCount = activeYear ? (draft.years[activeYear] ?? []).length : 0;
  const lastYear = years[years.length - 1];
  const yearToAdd = lastYear ? Number(lastYear) + 1 : currentYear;
  const copyTarget = activeYear ? String(Number(activeYear) + 1) : null;
  const canCopy = !!copyTarget && !draft.years[copyTarget];

  const edit = useCallback(
    (change: (current: CalendarDraft) => CalendarDraft) => {
      if (!activeId) return;
      setEdits((previous) => ({ ...previous, [activeId]: change(previous[activeId] ?? stored) }));
    },
    [activeId, stored],
  );

  useEffect(() => {
    const stop = () => setPainting(null);
    window.addEventListener('pointerup', stop);
    return () => window.removeEventListener('pointerup', stop);
  }, []);

  const onDayDown = useCallback(
    (cell: DayCell) => {
      if (!canEdit || cell.state === 'weekend') return;
      const mark = cell.state !== 'off';
      edit((current) => withDay(current, cell.day, mark));
      setPainting(mark);
    },
    [canEdit, edit],
  );

  const onDayEnter = useCallback(
    (cell: DayCell) => {
      if (painting === null || cell.state === 'weekend') return;
      edit((current) => withDay(current, cell.day, painting));
    },
    [painting, edit],
  );

  const toggleWeekday = useCallback(
    (weekday: number) => {
      if (!canEdit) return;
      edit((current) => withWeekday(current, weekday, !current.weekend.includes(weekday)));
    },
    [canEdit, edit],
  );

  const setName = useCallback((name: string) => edit((current) => ({ ...current, name })), [edit]);
  const setKey = useCallback((key: string) => edit((current) => ({ ...current, key })), [edit]);

  const selectCalendar = useCallback((id: string) => {
    setSelectedId(id);
    setYearChoice(null);
  }, []);

  const addYear = useCallback(() => {
    edit((current) => withYear(current, yearToAdd));
    setYearChoice(String(yearToAdd));
  }, [edit, yearToAdd]);

  const copyToNextYear = useCallback(() => {
    if (!activeYear || !copyTarget) return;
    edit((current) => copyYear(current, activeYear, copyTarget));
    setYearChoice(copyTarget);
    notify(t('view.copy-year.done', { from: activeYear, to: copyTarget }), 'info');
  }, [activeYear, copyTarget, edit, notify, t]);

  const discard = useCallback(() => {
    if (!activeId) return;
    setEdits((previous) => {
      const next = { ...previous };
      delete next[activeId];
      return next;
    });
  }, [activeId]);

  const otherKeys = useCallback(
    (id: string | null) => calendars.filter((calendar) => calendar.id !== id).map((calendar) => calendar.key),
    [calendars],
  );

  const save = useCallback(async () => {
    if (!collection || !activeId) return;
    const key = draft.key.trim();
    if (!isValidKey(key)) {
      notify(t('view.key.invalid'), 'error');
      return;
    }
    if (isKeyTaken(key, otherKeys(activeId))) {
      notify(t('view.key.taken', { key }), 'error');
      return;
    }
    setSaving(true);
    try {
      await updateRecord(collection, activeId, {
        name: draft.name.trim(),
        key,
        weekend: draft.weekend,
        years: draft.years,
      });
      discard();
      notify(t('view.saved'), 'success');
    } catch {
      notify(t('view.failed'), 'error');
    } finally {
      setSaving(false);
    }
  }, [collection, activeId, draft, otherKeys, updateRecord, discard, notify, t]);

  const createCalendar = useCallback(async () => {
    if (!collection) return;
    const name = t('view.new-calendar.name');
    try {
      const created = await createRecord(collection, {
        name,
        key: freeKey(name, otherKeys(null)),
        weekend: [0, 6],
        years: { [String(currentYear)]: [] },
      });
      if (created?.id) selectCalendar(created.id);
    } catch {
      notify(t('view.failed'), 'error');
    }
  }, [collection, createRecord, currentYear, notify, otherKeys, selectCalendar, t]);

  const askDelete = useCallback(() => setConfirmation({ kind: 'delete' }), []);
  const askRemoveYear = useCallback((year: string) => setConfirmation({ kind: 'remove-year', year }), []);
  const cancelConfirmation = useCallback(() => setConfirmation(null), []);

  const confirm = useCallback(async () => {
    const current = confirmation;
    setConfirmation(null);
    if (!current) return;
    if (current.kind === 'remove-year') {
      edit((draftNow) => withoutYear(draftNow, current.year));
      setYearChoice(null);
      return;
    }
    if (!collection || !activeId) return;
    try {
      await deleteRecord(collection, activeId);
      discard();
      setSelectedId(null);
    } catch {
      notify(t('view.failed'), 'error');
    }
  }, [confirmation, edit, collection, activeId, deleteRecord, discard, notify, t]);

  const confirmTitle =
    confirmation?.kind === 'delete'
      ? t('view.delete.title', { name: draft.name || draft.key })
      : confirmation?.kind === 'remove-year'
        ? t('view.remove-year.title', { year: confirmation.year })
        : '';
  const confirmMessage =
    confirmation?.kind === 'delete'
      ? t('view.delete.message')
      : confirmation?.kind === 'remove-year'
        ? t('view.remove-year.message', { year: confirmation.year })
        : '';
  const confirmLabel = confirmation?.kind === 'delete' ? t('view.delete.confirm') : t('view.remove.confirm');

  return {
    t,
    isLoading: entity.isLoading,
    screenMissing: !entity.isLoading && !entity.screen,
    calendars,
    activeId,
    selectCalendar,
    hasCalendar: !!record,
    draft,
    isDirty,
    saving,
    canEdit,
    canCreate,
    canDelete,
    weekdayNames,
    weekdayInitials,
    years,
    activeYear,
    selectYear: setYearChoice,
    yearToAdd,
    copyTarget,
    canCopy,
    months,
    markedCount,
    onDayDown,
    onDayEnter,
    toggleWeekday,
    setName,
    setKey,
    addYear,
    copyToNextYear,
    save,
    discard,
    createCalendar,
    askDelete,
    askRemoveYear,
    confirmation,
    confirmTitle,
    confirmMessage,
    confirmLabel,
    confirm,
    cancelConfirmation,
  };
};

// --- BusinessDays.styles.tsx ---
import { styled } from 'styled-components';

/**
 * Every colour, size, space and radius comes from the theme. A day that is not a business day uses
 * the theme's danger pair, a weekday that is never one uses the muted text — the grid has to read the
 * same in a light and a dark theme.
 */
const Missing = styled.div`
  padding: ${({ theme }) => theme.spacing.lg};
`;

const Layout = styled.div`
  display: grid;
  grid-template-columns: minmax(200px, 260px) 1fr;
  gap: ${({ theme }) => theme.spacing.lg};
  align-items: start;

  @media (max-width: 900px) {
    grid-template-columns: 1fr;
  }
`;

const Panel = styled.div`
  background: ${({ theme }) => theme.colors.surface};
  border: 1px solid ${({ theme }) => theme.colors.border};
  border-radius: ${({ theme }) => theme.borderRadius.lg};
  padding: ${({ theme }) => theme.spacing.md};
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.md};
  min-width: 0;
`;

const PanelTitle = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  font-weight: 600;
  color: ${({ theme }) => theme.colors.textSecondary};
`;

const CalendarList = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.xs};
`;

const CalendarItem = styled.button<{ $active?: boolean }>`
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  width: 100%;
  text-align: left;
  padding: ${({ theme }) => theme.spacing.sm} ${({ theme }) => theme.spacing.md};
  border-radius: ${({ theme }) => theme.borderRadius.md};
  border: 1px solid ${({ $active, theme }) => ($active ? theme.colors.primary : 'transparent')};
  background: ${({ $active, theme }) => ($active ? theme.colors.primaryLight : 'transparent')};
  color: ${({ theme }) => theme.colors.text};
  cursor: pointer;

  &:hover {
    background: ${({ $active, theme }) => ($active ? theme.colors.primaryLight : theme.colors.cardHover)};
  }
`;

const CalendarName = styled.span`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  font-weight: 600;
`;

const CalendarKey = styled.span`
  font-family: ${({ theme }) => theme.fonts.mono};
  font-size: ${({ theme }) => theme.fontSizes.xs};
  color: ${({ theme }) => theme.colors.textMuted};
`;

const Muted = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  color: ${({ theme }) => theme.colors.textMuted};
`;

const FieldRow = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: ${({ theme }) => theme.spacing.md};

  @media (max-width: 640px) {
    grid-template-columns: 1fr;
  }
`;

